package server.bots;import client.Character;import scripting.event.EventManager;import org.junit.jupiter.api.Test;import javax.script.*;import java.nio.file.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BotMvpqNpcTest {
 public static class Conversation {public final Character player=mock(Character.class);public final EventManager event=mock(EventManager.class);public String menu="",answer="";public Character getPlayer(){return player;}public EventManager getEventManager(String n){return event;}public boolean isUsingOldPqNpcStyle(){return false;}public void sendSimple(String s){menu=s;}public void sendOk(String s){answer=s;}public void dispose(){}}
 private ScriptEngine open(Conversation cm)throws Exception{var e=new ScriptEngineManager().getEngineByName("graal.js");var b=e.getBindings(ScriptContext.ENGINE_SCOPE);b.put("polyglot.js.allowHostAccess",true);b.put("polyglot.js.allowHostClassLookup",true);b.put("cm",cm);e.eval(Files.readString(Path.of("scripts/npc/9220018.js")));e.eval("start();");return e;}
 @Test void charlesKeepsNormalEntryAndAddsSeparateCrewChoices()throws Exception{var cm=new Conversation();try(var c=mockStatic(BotMvpqCompanions.class)){c.when(()->BotMvpqCompanions.assemble(cm.player)).thenReturn("crew ready");var e=open(cm);assertTrue(cm.menu.contains("I want to participate"));assertTrue(cm.menu.contains("BotPQ Menu"));assertTrue(cm.menu.contains("#L900#"));e.eval("action(1,4,900);");assertEquals("crew ready",cm.answer);c.verify(()->BotMvpqCompanions.assemble(cm.player));}}
 @Test void dismissalUsesTheAssignedCrewHandler()throws Exception{var cm=new Conversation();try(var c=mockStatic(BotMvpqCompanions.class)){c.when(()->BotMvpqCompanions.release(cm.player)).thenReturn("dismissed");var e=open(cm);e.eval("action(1,4,901);");assertEquals("dismissed",cm.answer);c.verify(()->BotMvpqCompanions.release(cm.player));}}
}
